from pathlib import Path
import subprocess
root=Path('.').resolve()
native=root/'native'
crate=root/'native/inir-mega/src'
files=['main.rs','pty.rs','feature_gates.rs','column_fixtures.rs','snapshot_lifecycle.rs','vendor_process.rs','sync_read.rs','transfer_read.rs','transfer_snapshot_lifecycle.rs','mutation_lock.rs','mutation_journal.rs','backend_identity.rs','diagnostic_sanitizer.rs']
r=subprocess.run(['cargo','fmt','--package','inir-mega'],cwd=native,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
if r.returncode!=0: raise SystemExit(240)
changed=subprocess.run(['git','diff','--name-only','--','native/inir-mega'],cwd=root,text=True,capture_output=True,check=True).stdout.splitlines()
expected={str((crate/f).relative_to(root)):i+1 for i,f in enumerate(files)}
unknown=[p for p in changed if p not in expected]
if unknown: raise SystemExit(241)
if not changed: raise SystemExit(242)
if len(changed)==1: raise SystemExit(expected[changed[0]])
raise SystemExit(100+len(changed))
